import React from "react";

const kasus = [
  'BEC rugi $10 juta.',
  'Rekrutmen palsu LinkedIn.',
];

export default function Slide10StudiKasus({ onNext, onPrev }) {
  return (
    <div className="slide-content bg-gradient-to-r from-[#ede7f6] to-[#d1c4e9] rounded-2xl p-8 md:p-12 shadow-xl">
      <h2 className="slide-title mb-6 text-purple-700">Studi Kasus Nyata</h2>
      <ul className="text-lg text-gray-800 mb-6 space-y-3">
        {kasus.map((k, i) => (
          <li key={i} className="flex items-center gap-3"><span className="text-purple-600">📄</span>{k}</li>
        ))}
      </ul>
      <div className="text-gray-700 mb-8">Bukan hanya orang awam, eksekutif pun bisa tertipu.</div>
      <div className="flex gap-4 justify-center">
        <button onClick={onPrev} className="bg-gray-200 text-purple-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-300 transition">Back</button>
        <button onClick={onNext} className="bg-purple-600 text-white px-6 py-2 rounded-lg font-bold text-lg shadow hover:bg-purple-700 transition">Next</button>
      </div>
    </div>
  );
}
